    permitsRank2024: 8,
    confidence: "estimated",
    note: "Carolinas growth corridor above replacement",
  },
  {
    id: "orlando",
    label: "Orlando???Kissimmee???Sanford, FL",
    short: "Orlando",
    band: "sun_belt",
    permits2024: 24135,
    netHhFormation: 19800,
    permitsPerNetHh: 1.22,
    permitsRank2024: 9,
    confidence: "estimated",
    note: "Central Florida permits exceed ACS household growth",
  },
  {
    id: "austin",
    label: "Austin???Round Rock???San Marcos, TX",
    short: "Austin",
    band: "sun_belt",
    permits2024: 32294,
    netHhFormation: 21800,
    permitsPerNetHh: 1.48,
    permitsRank2024: 6,
    confidence: "estimated",
    note: "Highest ratio in panel ??? permits still elevated vs formation cool-down",
  },
];

export type BandSummary = {
  band: MetroBand;
  label: string;
  metroCount: number;
  medianRatio: number;
  meanRatio: number;
  shareBelowOnePct: number;
};

export const BAND_SUMMARIES: BandSummary[] = [
  {
    band: "coastal_constrained",
    label: "Coastal constrained",
    metroCount: 6,
    medianRatio: 0.565,
    meanRatio: 0.54,
    shareBelowOnePct: 100,
  },
  {
    band: "interior",
    label: "Interior",
    metroCount: 2,
    medianRatio: 0.715,
    meanRatio: 0.715,
    shareBelowOnePct: 100,
  },
  {
    band: "sun_belt",
    label: "Sun Belt",
    metroCount: 8,
    medianRatio: 1.075,
    meanRatio: 1.06,
    shareBelowOnePct: 37.5,
  },
];

export function fmtK(n: number, digits = 0): string {
  if (Math.abs(n) >= 1000) return `${(n / 1000).toFixed(digits)}M`.replace(/\.0M$/, "M");
  return `${n.toFixed(digits)}k`;
}

export function fmtRatio(n: number): string {
  return n.toFixed(2);
}

export function fmtInt(n: number): string {
  return Math.round(n).toLocaleString("en-US");
}

export function nationalPathChart() {
  return NATIONAL_PATH.filter((r) => r.netHhFormationK != null).map((r) => ({
    year: String(r.year),
    permitsK: r.permitsK,
    formationK: r.netHhFormationK as number,
    ratio: r.permitsPerNetHh as number,
  }));
}

export function structureMixChart() {
  return STRUCTURE_MIX.map((r) => ({
    year: String(r.year),
    singleFamilyK: r.singleFamilyK,
    multiFamilyK: r.multiFamilyK,
    multiSharePct: r.multiSharePct,
  }));
}

export function regionDonut() {
  return REGION_PERMITS_2024.map((r) => ({
    name: r.label,
    value: r.permits2024k,
    sharePct: r.sharePct,
  }));
}

export function metroRatioBars(band: MetroBand | "all" = "all") {
  const rows =
    band === "all" ? [...METROS] : METROS.filter((m) => m.band === band);
  return rows
    .slice()
    .sort((a, b) => a.permitsPerNetHh - b.permitsPerNetHh)
    .map((m) => ({
      metro: m.short,
      ratio: m.permitsPerNetHh,
      permits: m.permits2024,
      formation: m.netHhFormation,
      band: m.band,
      below: m.permitsPerNetHh < 1,
    }));
}

export function metroScatter(band: MetroBand | "all" = "all") {
  const rows =
    band === "all" ? METROS : METROS.filter((m) => m.band === band);
  return rows.map((m) => ({
    metro: m.short,
    permitsK: m.permits2024 / 1000,
    formationK: m.netHhFormation / 1000,
    ratio: m.permitsPerNetHh,
    band: m.band,
    z: Math.max(8, Math.min(40, m.permits2024 / 2500)),
  }));
}

export function bandSummaryBars() {
  return BAND_SUMMARIES.map((b) => ({
    band: b.label,
    medianRatio: b.medianRatio,
    meanRatio: b.meanRatio,
    belowOnePct: b.shareBelowOnePct,
  }));
}

export const TABLE_ROWS = METROS.map((m) => ({
  metro: m.label,
  short: m.short,
  band: m.band,
  permits2024: m.permits2024,
  netHhFormation: m.netHhFormation,
  ratio: m.permitsPerNetHh,
  rank: m.permitsRank2024,
}));

