                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="band" tick={{ fontSize: 11 }} />
                  <YAxis yAxisId="left" domain={[0, 1.4]} tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    domain={[0, 100]}
                    tick={{ fontSize: 12 }}
                  />
                  <Tooltip />
                  <Legend />
                  <ReferenceLine yAxisId="left" y={1} stroke={SLATE} strokeDasharray="4 4" />
                  <Bar
                    yAxisId="left"
                    dataKey="medianRatio"
                    name="Median ratio"
                    fill={TEAL}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="belowOnePct"
                    name="% metros &lt; 1.0"
                    stroke={ROSE}
                    strokeWidth={2.5}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-3 space-y-1 text-xs text-slate-600">
              {BAND_SUMMARIES.map((b) => (
                <li key={b.band}>
                  <span className="font-semibold text-slate-800">{b.label}:</span>{" "}
                  median {fmtRatio(b.medianRatio)}, {b.shareBelowOnePct}% below
                  replacement
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      {view === "structure" && (
        <ChartCard
          title="Single-family vs multifamily authorizations"
          subtitle="Estimated BPS structure mix ?? stacked thousands + multi share line"
        >
          <div className="h-96 w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={structure} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                <YAxis yAxisId="left" tick={{ fontSize: 12 }} />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  domain={[30, 50]}
                  tick={{ fontSize: 12 }}
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="singleFamilyK"
                  name="1-unit (k)"
                  stackId="1"
                  fill={TEAL}
                  stroke={TEAL}
                  fillOpacity={0.85}
                />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="multiFamilyK"
                  name="2+ units (k)"
                  stackId="1"
                  fill={AMBER}
                  stroke={AMBER}
                  fillOpacity={0.85}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="multiSharePct"
                  name="Multi share %"
                  stroke={NAVY}
                  strokeWidth={2.5}
                  dot={{ r: 3 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

