/**
 * QA: us-housing-permits-vs-household-formation-2026
 * // viz-types: national composed permits+formation+ratio, metro ratio bars, permits??formation scatter, region donut, structure area, band median bars | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  HEADLINE,
  METROS,
  NATIONAL_PATH,
  REGION_PERMITS_2024,
  STRUCTURE_MIX,
} from "../src/data/us-housing-permits-vs-household-formation-2026-data.ts";

assert.equal(HEADLINE.permits2024k, 1478);
assert.equal(HEADLINE.netHhFormation2024k, 1525);
assert.ok(Math.abs(HEADLINE.permitsPerNetHh2024 - 0.969) < 0.002);
assert.ok(METROS.length >= 12);
assert.ok(NATIONAL_PATH.length >= 8);
assert.ok(STRUCTURE_MIX.length >= 5);
assert.ok(
  Math.abs(REGION_PERMITS_2024.reduce((s, r) => s + r.sharePct, 0) - 100) < 1.5,
);
assert.ok(METROS.every((m) => m.permitsPerNetHh > 0));
assert.equal(
  METROS.slice().sort((a, b) => a.permitsPerNetHh - b.permitsPerNetHh)[0].id,
  "boston",
);

const root = process.cwd();
const slug = "us-housing-permits-vs-household-formation-2026";
const markers = [
  "Housing permits ?? supply vs household formation",
  "0.97 permits per net household",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4188);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "National path");
    await clickBtn(page, "Metro ratios");
    await clickBtn(page, "All metros");
    await clickBtn(page, "Coastal");
    await clickBtn(page, "Sun Belt");
    await clickBtn(page, "Ratio bars");
    await clickBtn(page, "Permits ?? formation");
    await clickBtn(page, "Regions");
    await clickBtn(page, "Structure mix");
    await clickBtn(page, "National path");
    await auditVizInteractions(page, {
      slug,
      maxButtons: 14,
    });
    console.log(`qa-${slug}: PASS`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

