"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  BAND_SUMMARIES,
  HEADLINE,
  SOURCE_NOTE,
  bandSummaryBars,
  fmtInt,
  fmtRatio,
  metroRatioBars,
  metroScatter,
  nationalPathChart,
  regionDonut,
  structureMixChart,
  type MetroBand,
} from "@/data/us-housing-permits-vs-household-formation-2026-data";

// viz-types: national composed permits+formation+ratio, metro ratio bars, permits??formation scatter, region donut, structure area, band median bars | layout: default

type ViewId = "national" | "metros" | "regions" | "structure";
type BandFilter = MetroBand | "all";
type MetroMetric = "ratio" | "scatter";

const TEAL = "#0f766e";
const AMBER = "#b45309";
const NAVY = "#0f172a";
const SLATE = "#64748b";
const ROSE = "#be123c";
const SKY = "#0369a1";
const PIE_COLORS = [AMBER, TEAL, SKY, "#7c3aed"];
const BAND_COLORS: Record<MetroBand, string> = {
  coastal_constrained: ROSE,
  interior: SKY,
  sun_belt: TEAL,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function UsHousingPermitsVsHouseholdFormation2026Dashboard() {
  const [view, setView] = useState<ViewId>("national");
  const [band, setBand] = useState<BandFilter>("all");
  const [metroMetric, setMetroMetric] = useState<MetroMetric>("ratio");

  const national = useMemo(() => nationalPathChart(), []);
  const structure = useMemo(() => structureMixChart(), []);
  const regions = useMemo(() => regionDonut(), []);
  const bandBars = useMemo(() => bandSummaryBars(), []);
  const metroBars = useMemo(() => metroRatioBars(band), [band]);
  const scatter = useMemo(() => metroScatter(band), [band]);

  return (
    <div
      className="space-y-6"
      data-viz="us-housing-permits-vs-household-formation-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-teal-950 px-5 py-5 text-white sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-teal-200/90">
          Housing permits ?? supply vs household formation
        </p>
        <p className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          {HEADLINE.permitsPerNetHh2024Rounded} permits per net household
        </p>
        <p className="mt-2 max-w-3xl text-sm text-slate-300">
          Census BPS authorized{" "}
          <span className="font-semibold text-white">
            {fmtInt(HEADLINE.permits2024k)}k
          </span>{" "}
          units in 2024 against{" "}
          <span className="font-semibold text-white">
            {fmtInt(HEADLINE.netHhFormation2024k)}k
          </span>{" "}
          HVS net new households ??? a national ratio of{" "}
          <span className="font-semibold text-amber-300">
            {fmtRatio(HEADLINE.permitsPerNetHh2024)}
          </span>
          . {HEADLINE.furthestBelowMetro} sits furthest below replacement in the
          metro panel ({fmtRatio(HEADLINE.furthestBelowRatio)}).
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "national", label: "National path" },
            { id: "metros", label: "Metro ratios" },
            { id: "regions", label: "Regions" },
            { id: "structure", label: "Structure mix" },
          ]}
        />
        {view === "metros" && (
          <div className="flex flex-wrap gap-3">
            <ToggleGroup
              label="Band"
              value={band}
              onChange={setBand}
              options={[
                { id: "all", label: "All metros" },
                { id: "coastal_constrained", label: "Coastal" },
                { id: "sun_belt", label: "Sun Belt" },
                { id: "interior", label: "Interior" },
              ]}
            />
            <ToggleGroup
              label="Lens"
              value={metroMetric}
              onChange={setMetroMetric}
              options={[
                { id: "ratio", label: "Ratio bars" },
                { id: "scatter", label: "Permits ?? formation" },
              ]}
            />
          </div>
        )}
      </div>

      {view === "national" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Permits vs net household formation"
            subtitle="Thousands of units / households ?? BPS + HVS"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={national} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="permitsK" name="Permits (k)" fill={TEAL} radius={[4, 4, 0, 0]} />
                  <Line
                    type="monotone"
                    dataKey="formationK"
                    name="Net HH formation (k)"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Permits per net household"
            subtitle="Ratio ?? 1.0 = one authorized unit per net new household"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={national} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis domain={[0, 2.8]} tick={{ fontSize: 12 }} />
                  <Tooltip />
                  <ReferenceLine y={1} stroke={SLATE} strokeDasharray="4 4" label="1.0" />
                  <Area
                    type="monotone"
                    dataKey="ratio"
                    name="Permits / net HH"
                    fill={TEAL}
                    fillOpacity={0.15}
                    stroke={NAVY}
                    strokeWidth={2.5}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "metros" && metroMetric === "ratio" && (
        <ChartCard
          title="Metro permits per net household"
          subtitle="Sorted low ??? high ?? dashed line = replacement (1.0)"
        >
          <div className="h-[28rem] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={metroBars}
                layout="vertical"
                margin={{ top: 8, right: 16, left: 8, bottom: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis type="number" domain={[0, 1.6]} tick={{ fontSize: 12 }} />
                <YAxis
                  type="category"
                  dataKey="metro"
                  width={88}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip />
                <ReferenceLine x={1} stroke={SLATE} strokeDasharray="4 4" />
                <Bar dataKey="ratio" name="Permits / net HH" radius={[0, 4, 4, 0]}>
                  {metroBars.map((row) => (
                    <Cell
                      key={row.metro}
                      fill={row.below ? ROSE : TEAL}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "metros" && metroMetric === "scatter" && (
        <ChartCard
          title="Permits ?? household formation"
          subtitle="Bubble size scales with permit volume ?? color = band"
        >
          <div className="h-96 w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 0, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="formationK"
                  name="HH formation (k)"
                  tick={{ fontSize: 12 }}
                  label={{ value: "Net HH formation (k)", position: "insideBottom", offset: -2, fontSize: 11 }}
                />
                <YAxis
                  type="number"
                  dataKey="permitsK"
                  name="Permits (k)"
                  tick={{ fontSize: 12 }}
                  label={{ value: "Permits (k)", angle: -90, position: "insideLeft", fontSize: 11 }}
                />
                <ZAxis type="number" dataKey="z" range={[60, 400]} />
                <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                <ReferenceLine
                  segment={[
                    { x: 0, y: 0 },
                    { x: 100, y: 100 },
                  ]}
                  stroke={SLATE}
                  strokeDasharray="4 4"
                />
                {(["coastal_constrained", "sun_belt", "interior"] as MetroBand[]).map(
                  (b) => (
                    <Scatter
                      key={b}
                      name={b.replace("_", " ")}
                      data={scatter.filter((d) => d.band === b)}
                      fill={BAND_COLORS[b]}
                    />
                  ),
                )}
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Points above the 45?? guide permitted more units than net new
            households; coastal metros cluster below.
          </p>
        </ChartCard>
      )}

      {view === "regions" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="2024 permit share by Census region"
            subtitle="BPS annual ?? thousands of units"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={regions}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={58}
                    outerRadius={100}
                    paddingAngle={2}
                    label={({ name, sharePct }) => `${name} ${sharePct}%`}
                  >
                    {regions.map((_, i) => (
                      <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Band median permits / net HH"
            subtitle="Metro panel medians ?? % of metros below 1.0"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={bandBars} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="band" tick={{ fontSize: 11 }} />
                  <YAxis yAxisId="left" domain={[0, 1.4]} tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    domain={[0, 100]}
                    tick={{ fontSize: 12 }}
                  />
                  <Tooltip />
                  <Legend />
                  <ReferenceLine yAxisId="left" y={1} stroke={SLATE} strokeDasharray="4 4" />
                  <Bar
                    yAxisId="left"
                    dataKey="medianRatio"
                    name="Median ratio"
